        "\n",
        "    question = input(\n",
        "        \"\\nAsk a question (or 'exit'): \"\n",
        "    ).strip()\n",
        "\n",
        "    if question.lower() == \"exit\":\n",
        "        print(\"Session ended.\")\n",
        "        break\n",
        "\n",
        "    if not question:\n",
        "        continue\n",
        "\n",
        "    answer = ask_pdf(question)\n",
        "\n",
        "    print(\"\\nBest Matching PDF Content:\")\n",
        "    print(answer)\n"
